// Reads DOM globals Node does not define; the unresolved names must lower
// to Node's ReferenceError at the read and to "undefined" under typeof.
interface FrameProvider {
  schedule(callback: FrameRequestCallback): number;
  request: typeof requestAnimationFrame;
  delegate: { request: typeof requestAnimationFrame } | undefined;
}

const frames: FrameProvider = {
  schedule(callback) {
    const request = requestAnimationFrame;
    return request(callback);
  },
  request: undefined as never,
  delegate: undefined,
};

export function hasFrames(): string {
  return typeof requestAnimationFrame;
}

export function tryFrame(): string {
  try {
    frames.schedule(() => {});
    return "scheduled";
  } catch (e) {
    return `${(e as Error).name}: ${(e as Error).message}`;
  }
}
